<?php
declare(strict_types=1); namespace Hls\Controllers; use Hls\Http\View; use Hls\Repositories\Repository; use Hls\Middleware\Access;
final class FinancePaymentHistoryController { public function __construct(private Repository $repo,private View $view,private Access $access){} public function show():void{$this->access->demand('finance.receivable.view');$rows=$this->repo->all('SELECT p.*,a.code account_code,c.name customer_name,i.official_number,pa.amount allocated FROM fin_payments p JOIN fin_accounts a ON a.id=p.account_id JOIN fin_payment_allocations pa ON pa.payment_id=p.id JOIN fin_invoices i ON i.id=pa.invoice_id JOIN md_customers c ON c.id=i.customer_id WHERE p.branch_id IN (SELECT branch_id FROM user_branches WHERE user_id=? UNION SELECT id FROM branches WHERE ?=1) ORDER BY p.id DESC',[$this->access->user['id'],$this->access->user['all_branches']]);$this->view->render('finance-payment-history',['title'=>'Riwayat Pembayaran','rows'=>$rows]);}}
